/* --------------------------------------------------------------------------
   Persistence
   -------------------------------------------------------------------------- */
const Store = {
  get(key, fallback) {
    try {
      const raw = localStorage.getItem('bd84:' + key);
      return raw === null ? fallback : JSON.parse(raw);
    } catch (_) { return fallback; }
  },
  set(key, value) {
    try { localStorage.setItem('bd84:' + key, JSON.stringify(value)); }
    catch (_) { /* private mode, file://, etc. */ }
  },
};

