const midiFreq = (m) => 440 * Math.pow(2, (m - 69) / 12);

function buildArp(chords, pattern) {
  const out = [];
  for (let bar = 0; bar < 8; bar++) {
    const chord = chords[bar];
    for (let i = 0; i < 16; i++) out.push(chord[pattern[i]] || 0);
  }
  return out;
}

